# --------------------------------------------------------- # Check original landscape MP4 # --------------------------------------------------------- out_path = OUTPUT_DIR / filename file_exists = False file_size_mb = 0.0 if out_path.exists() and out_path.stat().st_size > 0: # Verify that FFmpeg can actually read the MP4 probe_cmd = [ "ffmpeg", "-v", "error", "-i", str(out_path), "-f", "null", "-" ] probe_result = subprocess.run( probe_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True ) if probe_result.returncode == 0: file_exists = True file_size_mb = ( out_path.stat().st_size / (1024 * 1024) ) else: print(f"[WARN] Invalid MP4: {out_path}") print(probe_result.stderr) # --------------------------------------------------------- # Create 9:16 face-tracked vertical version # --------------------------------------------------------- vertical_filename = ( f"{out_path.stem}_vertical.mp4" ) vertical_path = OUTPUT_DIR / vertical_filename vertical_exists = False if file_exists: print() print( f"Creating vertical version " f"for Scene #{s_idx}..." ) try: process_video( input_path=str(out_path), output_path=str(vertical_path), width=1080, height=1920, smooth_seconds=0.6, every=2, zoom=1.0, y_center=0.5 ) vertical_exists = ( vertical_path.exists() and vertical_path.stat().st_size > 0 ) except Exception as e: print( f"Vertical conversion failed " f"for Scene #{s_idx}: {e}" ) vertical_exists = False else: print( f"[WARN] Skipping vertical conversion " f"for Scene #{s_idx} because the " f"original MP4 is invalid or missing." ) # --------------------------------------------------------- # Vertical file size # --------------------------------------------------------- vertical_size_mb = ( vertical_path.stat().st_size / (1024 * 1024) if vertical_exists else 0.0 ) # --------------------------------------------------------- # Save result information # --------------------------------------------------------- shorts_created.append({ "video_title": v_title, "video_url": video_url, "scene_index": s_idx, "time_window": scene["time_window"], "heatmap_score": scene["heatmap_score"], "chapter": scene.get("chapter", "N/A"), # Original landscape short "mp4_file": str(out_path), "filename": filename, "size_mb": round(file_size_mb, 2), # 9:16 vertical short "vertical_mp4_file": str(vertical_path), "vertical_filename": vertical_filename, "vertical_size_mb": round( vertical_size_mb, 2 ), "status": ( "Success" if file_exists else "Failed" ), "vertical_status": ( "Success" if vertical_exists else "Failed" ) })